<template><section class="v2-page therapist-v2-page"><div v-if="loading" class="v2-state">正在读取训练详情…</div><div v-else-if="error" class="v2-state v2-state-error">{{ error }}</div><template v-else-if="detail"><header class="v2-page-header"><p class="v2-context">单次 TrainingSession</p><h1>{{ formatDate(detail.overview.started_at) }}</h1><p>{{ detail.overview.session_kind==='formal'?'正式计划训练':'额外练习' }} · {{ detail.overview.status }}</p></header><nav class="workspace-anchor-nav" aria-label="训练详情章节"><a href="#overview">概览</a><a href="#attempts">练习</a><a href="#facts">测量结果</a><a href="#evidence">证据</a><a href="#interpretation">观察与建议</a></nav><section id="overview" class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">Overview</p><h2>这次发生了什么</h2></div></div><div class="session-overview-strip"><div><strong>{{ detail.overview.exercises.length }}</strong><span>练习</span></div><div><strong>{{ completedCount }}</strong><span>完成</span></div><div><strong>{{ technicalCount }}</strong><span>技术原因未评分</span></div></div></section><section id="attempts" class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">Exercises / Attempts</p><h2>练习与作答</h2></div></div><div class="exercise-detail-list"><article v-for="exercise in detail.overview.exercises" :key="exercise.id"><div><strong>{{ exercise.order_index+1 }}. {{ exercise.title }}</strong><span>{{ exercise.exercise_type }} · {{ exercise.status }}</span></div><p>{{ exercise.target }}</p><small>提示等级 {{ exercise.prompt_level }} · {{ exercise.attempts.length }} 次作答</small></article></div></section><section id="facts" class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">Measurements</p><h2>专业指标</h2></div><p>明确区分本次测得、最近正式评估、未施测与不支持。</p></div><div class="metric-grid"><MetricPanel v-for="metric in detail.professional_metrics" :key="metric.code" :metric="metric"/></div></section><section id="evidence" class="workspace-band"><div class="workspace-band-heading"><div><p class="v2-section-label">Evidence & Quality</p><h2>证据与数据来源</h2></div></div><p v-if="!detail.evidence.length" class="v2-quiet-copy">当前没有可展示的证据投影。</p><details v-for="item in detail.evidence" :key="String(item.id)" class="evidence-row"><summary><strong>{{ item.type }}</strong><span>{{ item.quality_status }} · {{ item.source_status }}</span></summary><pre>{{ JSON.stringify(item,null,2) }}</pre></details></section><section id="interpretation" class="semantic-layers"><article class="layer facts"><p class="v2-section-label">FACTS</p><h2>测量结果</h2><p>上方指标来自 provider、规则或正式量表，不由 LLM 改写。</p></article><article class="layer observations"><p class="v2-section-label">SYSTEM OBSERVATIONS</p><h2>系统观察</h2><p v-if="!detail.observations.length">目前没有满足规则的长期观察。</p><p v-for="item in detail.observations" :key="String(item.id)">{{ item.statement }}</p></article><article class="layer recommendations"><p class="v2-section-label">CANDIDATE RECOMMENDATIONS</p><h2>系统建议</h2><p v-if="!detail.recommendations.length">目前没有候选建议。</p><p v-for="item in detail.recommendations" :key="String(item.id)">{{ item.candidate_action }}</p></article><article class="layer decision"><p class="v2-section-label">THERAPIST ACTION</p><h2>治疗师决定</h2><p>系统建议不会自动修改正式训练方案。请从患者工作区发起 Stage Review。</p></article></section></template></section></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { useRoute } from 'vue-router';import MetricPanel from '@/domain-ui/MetricPanel.vue';import { v2Api,type SessionDetailV2 } from '@/api/v2';import { toUserMessage } from '@/utils/errors';const route=useRoute();const detail=ref<SessionDetailV2|null>(null);const loading=ref(true);const error=ref('');const completedCount=computed(()=>detail.value?.overview.exercises.filter(x=>x.status==='completed').length||0);const technicalCount=computed(()=>detail.value?.overview.exercises.filter(x=>x.status==='technical_invalid').length||0);function formatDate(value:string|null){return value?new Intl.DateTimeFormat('zh-CN',{dateStyle:'long',timeStyle:'short'}).format(new Date(value)):'训练记录'}onMounted(async()=>{try{detail.value=await v2Api.therapistSession(String(route.params.sessionId))}catch(err){error.value=toUserMessage(err,'训练详情加载失败。')}finally{loading.value=false}});</script>
